scripts.script:
if (!args.isBroken || !args.target) return;
const eyuEffect = thisItem.effects.getName("恶语");
if (eyuEffect) {
    const existing = args.target.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_eyu");
    const stacks = existing ? (existing.getFlag("xjzl-system", "stacks") || 1) : 0;
    if (stacks >= 2) {
        await game.xjzl.api.effects.removeEffect(args.target, "wuxue_eyu", 3);
        await args.target.applyDamage({ amount: 10, type: "mental", attacker: actor, isHit: true, ignoreDefense: true });
        ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="padding: 4px 8px; border-left: 3px solid #8e44ad; background: rgba(142,68,173,0.05);"><div style="color:#8e44ad; font-weight:bold;"><i class="fas fa-comment-slash"></i> 恶语反噬！</div><div style="font-size:0.85em;">恶语叠满三层，在对方脑中炸开，受到 10 点精神伤害！</div></div>` });
    } else {
        const effData = eyuEffect.toObject();
        delete effData._id; effData.origin = thisItem.uuid;
        await game.xjzl.api.effects.addEffect(args.target, effData);
    }
}
ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="padding: 4px 8px; border-left: 3px solid #c0392b; background: rgba(192,57,43,0.05);"><div style="color:#c0392b; font-weight:bold;"><i class="fas fa-bolt"></i> 乘胜追击！</div><div style="font-size:0.85em;">击破架招成功！你可以消耗反应动作，立即释放实招【血口喷人】。</div></div>` });

if (!args.isHit || !args.target) return;
const eyuEffect = thisItem.effects.getName("恶语");
if (eyuEffect) {
    const existing = args.target.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_eyu");
    const stacks = existing ? (existing.getFlag("xjzl-system", "stacks") || 1) : 0;
    if (stacks >= 2) {
        await game.xjzl.api.effects.removeEffect(args.target, "wuxue_eyu", 3);
        await args.target.applyDamage({ amount: 10, type: "mental", attacker: actor, isHit: true, ignoreDefense: true });
        ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: `<div class="xjzl-chat-card" style="padding: 4px 8px; border-left: 3px solid #8e44ad; background: rgba(142,68,173,0.05);"><div style="color:#8e44ad; font-weight:bold;"><i class="fas fa-comment-slash"></i> 恶语反噬！</div><div style="font-size:0.85em;">恶语叠满三层，在对方脑中炸开，受到 10 点精神伤害！</div></div>` });
    } else {
        const effData = eyuEffect.toObject();
        delete effData._id; effData.origin = thisItem.uuid;
        await game.xjzl.api.effects.addEffect(args.target, effData);
    }
}

if (!Macros.checkStance(actor, args) || !args.attacker) return;
const eyuEffect = thisItem.effects.getName("恶语");
if (eyuEffect) {
    const existing = args.attacker.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_eyu");
    const stacks = existing ? (existing.getFlag("xjzl-system", "stacks") || 1) : 0;
    if (stacks >= 2) {
        await game.xjzl.api.effects.removeEffect(args.attacker, "wuxue_eyu", 3);
        await args.attacker.applyDamage({ amount: 10, type: "mental", attacker: actor, isHit: true, ignoreDefense: true });
        actor.showFloatyText("格挡反噬！", { fill: "#8e44ad" });
    } else {
        const effData = eyuEffect.toObject();
        delete effData._id; effData.origin = thisItem.uuid;
        await game.xjzl.api.effects.addEffect(args.attacker, effData);
        actor.showFloatyText("格挡: 施加恶语", { fill: "#e67e22" });
    }
}

if (!args.isHit || !args.target) return;
const hasEyu = args.target.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_eyu");

if (hasEyu) {
    // 【终极防并发】群攻中打中多个带恶语的目标时，防止音波被触发多次
    if (actor.zhongkouProcessed) return;
    actor.zhongkouProcessed = true;
    setTimeout(() => { actor.zhongkouProcessed = false; }, 2000);

    const neixi = actor.system.stats.neixi.total || 0;
    // 保底最少 1 点精神伤害
    const extraDmg = Math.max(1, Math.floor(neixi * 0.02));

    // 扫描画板上所有存活且带恶语的 Token
    const targetsToDamage = canvas.tokens.placeables.filter(t => 
        t.actor && t.actor.effects.some(e => e.getFlag("xjzl-system", "slug") === "wuxue_eyu")
    );

    // 自动扣血
    for (const t of targetsToDamage) {
        await t.actor.applyDamage({ amount: extraDmg, type: "mental", attacker: actor, isHit: true, ignoreDefense: true });
    }

    // 发送卡片
    ChatMessage.create({
        speaker: ChatMessage.getSpeaker({actor: actor}),
        content: `<div class="xjzl-chat-card" style="padding:4px 8px; border-left:4px solid #d35400; background:rgba(211,84,0,0.05); margin-left:2px;">
            <div style="color:#d35400; font-weight:bold;"><i class="fas fa-bullhorn"></i> 众口铄金 触发音波共振！</div>
            <div style="font-size:0.85em; margin-top:4px; color:#555;">
                全场共有 <b>${targetsToDamage.length}</b> 名带有[恶语]的敌人受到音波牵连，分别承受了 <b style="color:red;">${extraDmg}</b> 点精神伤害！
            </div>
        </div>`
    });
}

if (!Macros.checkStance(actor, args)) return;
const effData = thisItem.effects.getName("蛛心").toObject();
delete effData._id; effData.origin = thisItem.uuid;
// API 内置最大叠加层数保护（前提是我们在 JSON 中配置了 maxStacks）
await game.xjzl.api.effects.addEffect(actor, effData);
actor.showFloatyText("格挡: 隐秘结网", { fill: "#9b59b6" });

if (!args.isHit || !args.target) return;

// 1. 无架额外毒伤
if (!args.target.system.martial.stanceActive) {
    const qigan = actor.system.stats.qigan.total || 0;
    // 保底最少 1 点毒素伤害
    const poisonDmg = Math.max(1, Math.floor(qigan * 0.08));

    if (poisonDmg > 0) {
        // 自动造成毒素伤害
        await args.target.applyDamage({ amount: poisonDmg, type: "poison", attacker: actor, isHit: true });
        actor.showFloatyText(`无架追击: ${poisonDmg}毒伤`, {fill: "#2ecc71"});

        // 发送卡片
        ChatMessage.create({
            speaker: ChatMessage.getSpeaker({actor: actor}),
            content: `<div class="xjzl-chat-card" style="padding:4px 8px; border-left:4px solid #2ecc71; background:rgba(46,204,113,0.05); margin-left:2px;">
                <div style="color:#27ae60; font-weight:bold;"><i class="fas fa-spider"></i> 乘隙而入！</div>
                <div style="font-size:0.85em; margin-top:4px; color:#555;">
                    命中无架势目标，注入毒液造成 <b style="color:red;">${poisonDmg}</b> 点毒素伤害！
                </div>
            </div>`
        });
    }
}

// 2. 消耗蛛心施加迟滞
const zhuxin = actor.effects.find(e => e.getFlag("xjzl-system", "slug") === "wuxue_zhuxin");
const stacks = zhuxin ? (zhuxin.getFlag("xjzl-system", "stacks") || 1) : 0;

if (stacks >= 3) {
    const confirm = await foundry.applications.api.DialogV2.confirm({
        window: { title: "作丝绊足 - 蛛网收束" },
        content: `<p>你拥有 ${stacks} 层 [蛛心]。</p><p>是否全部消耗，使目标陷入 <b>[迟滞]</b> 一回合？</p>`
    });
    if (confirm) {
        await game.xjzl.api.effects.removeEffect(actor, "wuxue_zhuxin", 99);
        await game.xjzl.api.effects.addEffect(args.target, { id: "chizhi", duration: {rounds: 1} });
        ChatMessage.create({ 
            speaker: ChatMessage.getSpeaker({actor: actor}), 
            content: `<div class="xjzl-chat-card" style="padding:4px 8px; border-left:4px solid #2980b9; background:rgba(41,128,185,0.05); margin-left:2px;"><div style="color:#2980b9; font-weight:bold;"><i class="fas fa-network-wired"></i> 蛛网收束！</div><div style="font-size:0.85em; margin-top:4px; color:#555;">收割所有蛛心，目标陷入迟滞。</div></div>` 
        });
    }
}

if (!args.isBroken || !args.target) return;
const lvl = Math.max(1, move.computedLevel || 1);
const rounds = 1 + (lvl - 1);
await game.xjzl.api.effects.addEffect(args.target, { id: "blind", duration: { rounds: rounds } });
actor.showFloatyText("击破防线: 致盲", { fill: "#e74c3c" });

if (!args.isHit || !args.target) return;
const lvl = Math.max(1, move.computedLevel || 1);
const effData = thisItem.effects.getName("幻毒").toObject();
delete effData._id; effData.origin = thisItem.uuid;
// 记录来源招式的等级，方便幻毒AE内部读取
foundry.utils.setProperty(effData, "flags.xjzl-system.sourceLevel", lvl);
effData.duration = { rounds: 1 };
await game.xjzl.api.effects.addEffect(args.target, effData);

if (!args.isHit || !args.target) return;
await game.xjzl.api.effects.addEffect(args.target, { id: "prone" });

const shencaiMod = Math.floor((actor.system.stats.shencai.total || 0) / 10);
const roll = await new Roll("1d20 + @mod", {mod: shencaiMod}).evaluate();
if (game.dice3d) game.dice3d.showForRoll(roll, game.user, true);
await roll.toMessage({ speaker: ChatMessage.getSpeaker({actor: actor}), flavor: `天罗地网 - 神采牵丝 (DC 15)` });

if (roll.total >= 15) {
    const effData = thisItem.effects.getName("蛛心").toObject();
    delete effData._id; effData.origin = thisItem.uuid;
    await game.xjzl.api.effects.addEffect(actor, effData);
    actor.showFloatyText("成功牵网: +1 蛛心", { fill: "#9b59b6" });
}

const sourceLvl = thisEffect.getFlag("xjzl-system", "sourceLevel") || 1;
const rounds = 1 + (sourceLvl - 1);
await Macros.requestSave({
    target: actor,
    type: "renxing",
    dc: 12,
    label: "幻毒发作",
    damageOnFail: { value: 5, type: "poison" },
    onFail: { id: "unstable", duration: { rounds: rounds } },
    failureText: "幻毒发作，脚步虚浮！",
    successText: "凭惊人韧性压制了幻毒的爆发。"
});
